import {api,auth,ready,escapeHtml as esc,money} from './client.js';
import {deliveryFeeSummary} from '../delivery-fee.js';
const $=s=>document.querySelector(s),root=$('#pos'),dialog=$('#dialog');
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const uid=()=>crypto.randomUUID(),amount=n=>(Number(n||0)/100).toFixed(2);
const cents=v=>{if(!/^\d+(\.\d{1,2})?$/.test(String(v)))throw Error('Enter a positive amount with at most two decimal places.');const n=Math.round(Number(v)*100);if(!Number.isSafeInteger(n)||n>1000000000)throw Error('Amount is too large.');return n;};
const input=(name,label,value='',type='text',attrs='')=>`<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value??'')}" ${attrs}></label>`;
const opt=(v,label,selected)=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(label)}</option>`;
const select=(name,label,items,value)=>`<label>${esc(label)}<select name="${name}" aria-label="${esc(label)}">${items.map(([v,l])=>opt(v,l,value)).join('')}</select></label>`;
const button=(action,label,extra='')=>`<button type="button" data-action="${action}" ${extra}>${label}</button>`;
const status=m=>{$('#status').textContent=m;clearTimeout(status.timer);status.timer=setTimeout(()=>{$('#status').textContent='';},7000);};
let role='',mode='in_person',view='sale',catalog={products:[],pos_products:[],flavors:[],payment_options:[]},events=[],event=null,eventId='',orders=[],editing=null,busy=false,pending=null,report=null,reportDate=today(),search='';
const newDraft=()=>({items:[],fulfillment_date:today(),method:'pickup',buyer:{name:'',phone:'',email:''},recipient:{name:'',phone:''},address:{line1:'',line2:'',locality:'',postal_code:''},instructions:'',delivery_cents:0,delivery_fee_recipient:'elio',delivery_fee_pending:false,paid:mode==='in_person',pos_handed_over:mode==='in_person',payment:{method:'cash',cash_received_cents:0,reference:''},send_email:false});
let draft=newDraft();
function currentProducts(){return mode==='in_person'?(event?.items||[]):catalog.products;}
function product(id){return currentProducts().find(p=>p.id===id);}
function linePrice(i){if(i.source==='custom')return i.unit_price_cents; if(editing){const old=editing.items.find(x=>x.product_id===i.product_id&&JSON.stringify(x.selections||{})===JSON.stringify(i.selections||{}));if(old)return old.unit_price_cents;}const p=product(i.product_id);if(!p)return i.unit_price_cents||0;return Number(p.price_cents||0)+(p.kind==='custom_box'?Object.entries(i.selections?.flavors||{}).reduce((n,[id,q])=>n+(catalog.flavors.find(f=>f.id===id)?.price_cents||0)*q,0):0);}
const draftFee=()=>draft.method!=='delivery'?0:editing?draft.delivery_cents:draft.delivery_fee_pending||draft.delivery_fee_recipient==='courier'?0:draft.delivery_cents;
const draftCharge=()=>editing?draft.delivery_charge:mode==='direct'?{state:draft.delivery_fee_pending?'pending':draft.delivery_fee_recipient==='courier'?'courier':'included',recipient:draft.delivery_fee_recipient,fee_cents:draft.delivery_fee_pending?null:draft.delivery_cents}:null;
const estimated=()=>draft.items.reduce((n,i)=>n+linePrice(i)*i.quantity,0)+draftFee();
function deliveryFields(){if(mode!=='direct')return input('delivery_fee','Delivery fee · PHP',amount(draft.delivery_cents),'number','min="0" step="0.01" required');
 if(editing)return '<p>'+esc(deliveryFeeSummary(draft,money))+'</p><small>Use Edit delivery fee in the order list to change the amount or recipient.</small>';
 return select('delivery_fee_recipient','Customer pays delivery to',[['elio','Pay Elio'],['courier','Pay courier directly']],draft.delivery_fee_recipient)+select('delivery_fee_pending','Delivery fee',[['false','Exact fee known'],['true','Confirm after booking']],String(draft.delivery_fee_pending))+(draft.delivery_fee_pending?'<p class="muted">The delivery amount will be confirmed later.</p>':input('delivery_fee','Exact delivery fee · PHP',amount(draft.delivery_cents),'number','min="0" step="0.01" required'));
}
function flashError(error){const el=$('#page-error');if(el){el.hidden=false;el.textContent=error.message;el.scrollIntoView({block:'nearest'});}else status(error.message);}
function modal(title,html,onSubmit){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=html;dialog.showModal();const form=dialog.querySelector('form');if(form)form.onsubmit=async e=>{e.preventDefault();if(busy)return;const submit=form.querySelector('[type=submit]');try{busy=true;submit.disabled=true;await onSubmit(new FormData(form));}catch(error){let notice=form.querySelector('.error');if(!notice){notice=document.createElement('p');notice.className='notice error';form.prepend(notice);}notice.textContent=error.message;}finally{busy=false;submit.disabled=false;}};}
$('#close-dialog').onclick=()=>{if(!busy)dialog.close();};dialog.addEventListener('cancel',e=>{if(busy)e.preventDefault();});
async function load(){const [c,ev,os]=await Promise.all([api('pos_catalog',{date:draft.fulfillment_date}),api('pos_events'),api('pos_orders')]);catalog=c;events=ev;orders=os;if(eventId&&!events.some(x=>x.id===eventId))eventId='';if(eventId)event=await api('pos_event_data',{event_id:eventId,date:today()});else event=null;}
function render(){
 root.innerHTML=`<div class="row" aria-label="POS sections">${button('mode-person','In-person sales',`aria-pressed="${mode==='in_person'}" ${editing||pending?'disabled':''}`)}${button('mode-direct','Direct orders',`aria-pressed="${mode==='direct'}" ${editing||pending?'disabled':''}`)}</div><h1>${mode==='in_person'?'Event & pop-up POS':'Direct orders'}</h1><p class="muted">${mode==='in_person'?'Separate event stock and prices. Every sale is paid in full.':'Orders from messages and calls, with live website stock and shareable payment links.'}</p><p id="page-error" class="notice error" hidden></p>${!navigator.onLine?'<p class="notice error">You’re offline. Reconnect before checking stock or recording a sale.</p>':''}
 ${mode==='in_person'?`<div class="section-head"><label>Event<select id="event-select" ${editing||pending?'disabled':''}>${opt('','Choose an event',eventId)}${events.map(e=>opt(e.id,e.name+(e.active?'':' · closed'),eventId)).join('')}</select></label>${role==='owner'?button('new-event','+ Create event'):''}</div>`:''}
 <nav class="tabs" aria-label="POS pages">${[['sale',editing?'Edit order':'New sale'],['orders','Orders'],...(mode==='in_person'?[['report','Event report']]:[]),...(role==='owner'&&mode==='in_person'?[['setup','Event setup']]:[])].map(([id,label])=>button('view-'+id,label,`aria-pressed="${view===id}" ${pending?'disabled':''}`)).join('')}</nav>
 ${pending?renderReview():view==='orders'?renderOrders():view==='setup'?renderSetup():view==='report'?renderReport():renderSale()}`;
 bind();
}
function renderSale(){
 if(mode==='in_person'&&!event)return '<section class="panel empty">Choose an event to begin. The owner can create an event and enter its stock, items, and prices.</section>';
 const products=currentProducts().filter(p=>(p.active!==false||editing?.items.some(i=>i.product_id===p.id))&&p.name.toLowerCase().includes(search.toLowerCase()));
 const cash=event?.cash_session;
 return `${editing?`<p class="notice">Editing ${esc(editing.reference)}. Saved item prices are preserved. Changes are recorded in order history. ${button('cancel-edit','Leave editor')}</p>`:''}${mode==='in_person'&&!editing&&(!cash||cash.closed_at)?`<section class="panel"><h2>${cash?'Cash session closed':'Start today’s cash session'}</h2><p>Enter the opening float before the first sale. You can open with ₱0 if there is no cash float.</p>${cash?(role==='owner'?button('reopen-cash','Reopen cash session'):'<p>Ask the owner to reopen this cash session.</p>'):button('open-cash','Open cash session','class="primary"')}</section>`:''}
 <div class="sales-grid"><section class="panel"><div class="section-head"><h2>Choose items</h2>${mode==='direct'?button('custom-item','+ Add custom item'):'<small>Event stock only</small>'}</div><label class="search">Search items<input id="search" type="search" value="${esc(search)}" placeholder="Find a product"></label><div class="catalog">${products.map(p=>`<button type="button" class="product" data-add="${esc(p.id)}" ${p.active===false?'disabled':''}><strong>${esc(p.name)}</strong><span class="price">${money(p.price_cents)}</span><small>${p.kind==='custom_box'?'Choose 3 flavors · surcharges apply':p.source==='website'?'Shared website flavor stock':p.remaining===null?'Unlimited stock':`${p.remaining??0} available`}</small>${p.source==='website'&&p.stock_available===false?'<small>Check availability for the selected date</small>':''}</button>`).join('')||'<p class="empty">No items available. Check the event setup or choose another date.</p>'}</div></section>
 <section class="panel"><form id="sale-form"><h2>${editing?'Order details':'Your sale'}</h2><div id="cart">${draft.items.map((i,index)=>`<div class="cart-line"><div><strong>${esc(product(i.product_id)?.name||i.name||'Saved item')}</strong>${i.source==='custom'?button('edit-custom-item','Edit name / price',`data-id="${index}"`):''}<small>${money(linePrice(i))} each${i.selections?.flavors?' · '+Object.entries(i.selections.flavors).filter(([,q])=>q>0).map(([id,q])=>esc(q+' × '+(catalog.flavors.find(f=>f.id===id)?.name||'Saved flavor'))).join(', '):''}</small></div><input type="number" data-qty="${index}" aria-label="Quantity for ${esc(product(i.product_id)?.name||i.name)}" value="${i.quantity}" min="1" max="10000" step="1" required><button type="button" data-remove="${index}" aria-label="Remove item">×</button></div>`).join('')||'<p class="empty">Add items to your sale.</p>'}</div>
 <div class="subheading fields">${select('method','Fulfillment',[['pickup','Pickup'],['delivery','Delivery']],draft.method)}${input('fulfillment_date','Fulfillment date',draft.fulfillment_date,'date','required')}</div>
 ${mode==='direct'&&!editing?select('paid','Payment status',[['false','Unpaid · send a payment link'],['true','Paid · current Elio total']],String(draft.paid)):''}
 ${!editing?`<label class="check"><input type="checkbox" name="pos_handed_over" ${draft.pos_handed_over?'checked':''} ${!draft.paid||draft.method!=='pickup'||draft.fulfillment_date!==today()?'disabled':''}>Already handed to the customer</label>`:''}
 <details ${mode==='direct'||!draft.pos_handed_over?'open':''}><summary>Customer details · optional</summary><div class="subheading fields">${input('buyer_name','Customer name',draft.buyer.name,'text','maxlength="160"')}${input('buyer_phone','Contact number',draft.buyer.phone,'tel','maxlength="40"')}</div>${input('buyer_email','Email · optional',draft.buyer.email,'email','maxlength="254"')}<div class="fields">${input('social_platform','Social platform · optional',draft.buyer.social_platform||'','text','maxlength="50" placeholder="Instagram, Facebook…"')}${input('social_username','Username / profile · optional',draft.buyer.social_username||'','text','maxlength="160"')}</div></details>
 ${draft.method==='delivery'?`<div class="subheading"><h3>Delivery details</h3><div class="fields">${input('recipient_name','Recipient name',draft.recipient.name,'text','maxlength="160"')}${input('recipient_phone','Recipient phone',draft.recipient.phone,'tel','maxlength="40"')}</div>${button('copy-buyer','Use customer as recipient')}${input('line1','Street / building / unit',draft.address.line1,'text','maxlength="500"')}<div class="fields delivery-fields">${input('locality','Delivery area',draft.address.locality,'text','maxlength="160"')}${deliveryFields()}</div></div>`:''}
 <label class="subheading">Instructions · optional<textarea name="instructions" maxlength="2000">${esc(draft.instructions)}</textarea></label>
 ${draft.paid&&!editing?paymentFields(draft.payment):''}
 ${mode==='direct'&&!editing?`<label class="check"><input type="checkbox" name="send_email" ${draft.send_email?'checked':''}>Email order details and future order updates to the customer</label><small>The payment link stays open until proof is submitted or your team cancels the order. Stock stays reserved.</small>`:''}
 ${editing?input('reason','Reason for the edit',draft.reason||'','text','required maxlength="1000"'):''}
 <div class="totals"><div><span>Products</span><strong>${money(estimated()-draftFee())}</strong></div><div><span>Delivery</span><span>${esc(deliveryFeeSummary({...draft,delivery_charge:draftCharge()},money))}</span></div><div class="grand"><span>Total estimate</span><span>${money(estimated())}</span></div>${draft.paid&&draft.payment.method==='cash'&&!editing?`<div><span>Change</span><strong id="cash-change">${money(Math.max(0,draft.payment.cash_received_cents-estimated()))}</strong></div>`:''}</div><small>Review checks the current price and available stock before you record the sale.</small><button class="primary full subheading" type="submit" ${!draft.items.length||mode==='in_person'&&!editing&&(!cash||cash.closed_at)?'disabled':''}>Review ${editing?'changes':'sale'}</button></form></section></div>`;
}
function paymentFields(p){const methods=mode==='in_person'?['GCash','BDO','EastWest']:[...new Set((catalog.payment_options||[]).map(x=>x.label))];return `<div class="subheading"><h3>Payment received</h3>${select('payment_method','Payment method',[['cash','Cash'],...methods.map(x=>[x,x])],p.method)}${p.method==='cash'?input('cash_received','Cash received · PHP',amount(p.cash_received_cents),'number','min="0" step="0.01" required'):input('payment_reference','Payment reference · optional',p.reference,'text','maxlength="160"')}<small>Confirm the full payment was received before recording the sale.</small></div>`;}
function readDraft(){const f=$('#sale-form');if(!f)return;const v=new FormData(f),get=n=>String(v.get(n)||'');draft.method=get('method');draft.fulfillment_date=get('fulfillment_date');if(!editing){draft.paid=mode==='in_person'||get('paid')==='true';draft.pos_handed_over=draft.paid&&draft.method==='pickup'&&draft.fulfillment_date===today()&&v.has('pos_handed_over');draft.send_email=v.has('send_email');}
 draft.buyer={...draft.buyer,name:get('buyer_name'),phone:get('buyer_phone'),email:get('buyer_email'),social_platform:get('social_platform'),social_username:get('social_username')};if(draft.method==='delivery'){draft.recipient={name:get('recipient_name'),phone:get('recipient_phone')};draft.address={...draft.address,line1:get('line1'),locality:get('locality')};if(v.has('delivery_fee'))draft.delivery_cents=cents(get('delivery_fee')||'0');if(v.has('delivery_fee_recipient'))draft.delivery_fee_recipient=get('delivery_fee_recipient');if(v.has('delivery_fee_pending'))draft.delivery_fee_pending=get('delivery_fee_pending')==='true';}else draft.delivery_cents=0;
 draft.instructions=get('instructions');if(v.has('payment_method'))draft.payment={method:get('payment_method'),reference:get('payment_reference'),cash_received_cents:cents(get('cash_received')||'0')};if(editing)draft.reason=get('reason');}
function payload(){return {...structuredClone(draft),order_source:mode,...(mode==='in_person'?{event_id:eventId}:{}),items:draft.items.map(i=>({product_id:i.product_id,source:i.source,selections:i.selections||{},quantity:i.quantity,...(i.source==='custom'?{name:i.name,unit_price_cents:i.unit_price_cents}:{})}))};}
async function review(){readDraft();const sale=payload();if(editing){const changes=Object.fromEntries(['items','fulfillment_date','method','buyer','recipient','address','instructions','delivery_cents'].map(k=>[k,sale[k]]));const q=await api('preview_edit_order',{order_id:editing.id,revision:editing.revision,changes});pending={action:'edit_order',payload:{order_id:editing.id,revision:editing.revision,changes,reason:draft.reason,idempotency_key:uid(),expected_quote:Object.fromEntries(['items','subtotal_cents','discount_cents','delivery_cents','total_cents','delivery_zone_name','delivery_zone_description'].map(k=>[k,q[k]]))},quote:q};}else{const q=await api('pos_quote',sale);pending={action:'pos_create_order',payload:{...sale,idempotency_key:uid(),expected_quote:q},quote:q};}render();}
function renderReview(){const q=pending.quote;return `<section class="panel pending-review"><h2>${pending.attempted?'Confirming your saved request':'Review before recording'}</h2><p>${mode==='in_person'?esc(event?.name):'Direct order'} · ${esc(draft.method)} · ${esc(draft.fulfillment_date)}</p><div class="table-wrap"><table><thead><tr><th>Item</th><th>Quantity</th><th class="num">Amount</th></tr></thead><tbody>${q.items.map(i=>`<tr><td>${esc(i.name)}</td><td>${i.quantity}</td><td class="num">${money(i.line_total_cents)}</td></tr>`).join('')}</tbody></table></div><div class="totals"><div><span>Delivery</span><span>${esc(deliveryFeeSummary({...q,method:draft.method},money))}</span></div><div class="grand"><span>Total</span><strong>${money(q.total_cents)}</strong></div></div><p>${editing?'Save these order changes.':draft.paid?`Current Elio total paid · ${esc(draft.payment.method==='cash'?'Cash':draft.payment.method)}${draft.payment.method==='cash'?' · Change '+money(draft.payment.cash_received_cents-q.total_cents):''}`:'Unpaid · stock reserved until payment or cancellation.'}</p><p class="muted">${pending.attempted?'The same request will be retried safely. Stay on this screen if the connection drops.':'Recording this sale updates inventory and saves the order.'}</p><div class="row">${!pending.attempted?button('back-review','Back'):''}${button('save-sale',pending.attempted?'Retry saving this request':editing?'Save changes':'Record sale','class="primary"')}</div></section>`;}
async function saveSale(){if(!pending)return;pending.attempted=true;const req=pending;render();try{const o=await api(req.action,req.payload);pending=null;editing=null;draft=newDraft();await load();view='orders';render();showSaved(o);}catch(error){if(error.code==='P0001'||/^22|^23/.test(error.code||'')){pending.attempted=false;render();}throw error;}}
function showSaved(o){modal('Order saved',`<p class="notice success"><strong>${esc(o.reference)}</strong> · ${money(o.total_cents)} · ${esc(o.payment_status.replaceAll('_',' '))}</p>${o.pos_payment?.method==='cash'?`<p>Change to give: <strong>${money(o.pos_payment.change_cents)}</strong></p>`:''}<div class="row">${o.order_source==='direct'?button('payment-link','Copy payment / order link',`data-id="${o.id}"`):''}${button('open-order','View order',`data-id="${o.id}"`)}${button('next-sale','Next sale','class="primary"')}</div>`);}
function renderOrders(){const rows=orders.filter(o=>o.order_source===mode&&(mode!=='in_person'||!eventId||o.event_id===eventId));return `<section class="panel"><h2>Recent ${mode==='in_person'?'event sales':'direct orders'}</h2><p class="muted">Latest 200 POS orders. Use the Kitchen dashboard for the complete order history, payment-proof review, fulfillment, cancellation and refunds.</p><div class="table-wrap"><table><thead><tr><th>Order / customer</th><th>Fulfillment</th><th>Payment</th><th class="num">Total</th><th>Actions</th></tr></thead><tbody>${rows.map(o=>`<tr><td><strong>${esc(o.reference)}</strong><small>${esc(o.buyer?.name)}</small>${o.event_name?`<small>${esc(o.event_name)}</small>`:''}</td><td>${esc(o.method)}<small>${esc(o.fulfillment_date)} · ${esc(o.fulfillment_status.replaceAll('_',' '))}</small></td><td>${esc(o.payment_status.replaceAll('_',' '))}${o.refund_label?'<small>Refunded</small>':''}${o.order_source==='direct'&&o.method==='delivery'?`<small>${esc(deliveryFeeSummary(o,money))}</small>`:''}</td><td class="num">${money(o.total_cents)}</td><td><div class="row">${button('open-order','Open',`data-id="${o.id}"`)}${o.order_source==='direct'&&o.method==='delivery'&&!o.refund_label&&!['cancelled','expired'].includes(o.fulfillment_status)?button('delivery-fee','Edit delivery fee',`data-id="${o.id}"`):''}${mode==='direct'?button('payment-link','Copy payment link',`data-id="${o.id}"`):''}${o.payment_status==='awaiting_payment'&&o.fulfillment_status==='pending_confirmation'&&!o.refund_label?button('pay-order','Record payment',`data-id="${o.id}"`):''}${!o.refund_label&&!['completed','cancelled','expired'].includes(o.fulfillment_status)?button('edit-order','Edit',`data-id="${o.id}"`):''}</div></td></tr>`).join('')||'<tr><td colspan="5">No orders in this section.</td></tr>'}</tbody></table></div></section>`;}
function renderSetup(){if(mode==='direct')return `<section class="panel"><div class="section-head"><h2>POS-only products</h2>${button('new-product','+ Add product')}</div><p class="muted">These products stay off the website. Website box prices and inventory are managed in the Kitchen dashboard.</p><div class="table-wrap"><table><thead><tr><th>Product</th><th>Price</th><th>Stock</th><th>Actions</th></tr></thead><tbody>${catalog.pos_products.map(p=>`<tr><td>${esc(p.name)}<small>${p.active?'Available':'Hidden'} · ${esc(p.stock_mode)}</small></td><td>${money(p.price_cents)}</td><td>${p.remaining===null?'Unlimited':p.remaining}</td><td><div class="row">${button('edit-product','Edit',`data-id="${p.id}"`)}${p.stock_mode!=='unlimited'?button('stock-product','Adjust stock',`data-id="${p.id}"`):''}${button('delete-product','Delete',`data-id="${p.id}"`)}</div></td></tr>`).join('')||'<tr><td colspan="4">Add your first POS-only product.</td></tr>'}</tbody></table></div></section>`;
 if(!event)return '<p class="notice">Choose or create an event first.</p>';
 return `<section class="panel"><div class="section-head"><h2>${esc(event.name)}</h2>${button('edit-event','Edit event')}</div><p>${esc(event.starts_on)} – ${esc(event.ends_on)} · ${event.active?'Open':'Closed'}</p><p class="muted">Event stock is separate from the website. Add flavor pieces or other stock units below, then create sellable items and specify how many units each uses.</p></section><section class="panel"><div class="section-head"><h2>Event stock</h2>${button('new-event-stock','+ Add flavor / stock item')}</div><div class="table-wrap"><table><thead><tr><th>Flavor / stock unit</th><th class="num">Remaining</th><th>Actions</th></tr></thead><tbody>${event.stock.map(s=>`<tr><td>${esc(s.name)}</td><td class="num">${s.remaining}</td><td>${button('edit-event-stock','Adjust',`data-id="${s.id}"`)}</td></tr>`).join('')||'<tr><td colspan="3">Add the stock prepared for this event.</td></tr>'}</tbody></table></div></section><section class="panel"><div class="section-head"><h2>Sellable event items</h2>${button('new-event-item','+ Add event item',event.stock.length?'':'disabled')}</div><p class="muted">Example: a trio uses 1 Vanilla, 1 Chocolate, and 1 Matcha piece. Selling either a trio or a single piece deducts from the same event flavor stock.</p><div class="table-wrap"><table><thead><tr><th>Item / recipe</th><th>Event price</th><th>Available</th><th>Actions</th></tr></thead><tbody>${event.items.map(p=>`<tr><td><strong>${esc(p.name)}</strong><small>${p.recipe.map(r=>`${r.quantity} × ${esc(event.stock.find(s=>s.id===r.stock_id)?.name||'Stock item')}`).join(', ')}${p.active?'':' · Hidden'}</small></td><td>${money(p.price_cents)}</td><td>${p.remaining}</td><td>${button('edit-event-item','Edit',`data-id="${p.id}"`)}</td></tr>`).join('')||'<tr><td colspan="4">Create the items and prices for this event.</td></tr>'}</tbody></table></div></section>`;}
function eventForm(e){modal(e?'Edit event':'Create event',`<form>${input('name','Event name',e?.name||'','text','maxlength="160"')}<div class="fields">${input('starts_on','First day',e?.starts_on||today(),'date','required')}${input('ends_on','Last day',e?.ends_on||today(),'date','required')}</div><label class="check"><input name="active" type="checkbox" ${e?.active!==false?'checked':''}>Event open for sales</label><button class="primary" type="submit">Save event</button></form>`,async f=>{const saved=await api('pos_save_event',{event_id:e?.id||uid(),revision:e?.revision||0,name:f.get('name'),starts_on:f.get('starts_on'),ends_on:f.get('ends_on'),active:f.has('active')});eventId=saved.id;await load();view='setup';dialog.close();render();});}
function eventStockForm(s){modal(s?'Adjust event stock':'Add event stock',`<form>${input('name','Flavor / stock unit name',s?.name||'','text','maxlength="160"')}${input('available','Available pieces / units now',s?.remaining||0,'number','required min="0" max="1000000" step="1"')}${input('reason','Reason',s?'':'Initial event stock','text','required maxlength="1000"')}<p class="muted">This changes only this event’s stock. Sales already recorded stay in history.</p><button class="primary" type="submit">Save stock</button></form>`,async f=>{await api('pos_save_event_stock',{event_id:eventId,id:s?.id||uid(),revision:s?.revision||0,name:f.get('name'),available:Number(f.get('available')),expected_available:s?.remaining||0,reason:f.get('reason')});await load();dialog.close();render();});}
function eventItemForm(p){modal(p?'Edit event item':'Add event item',`<form>${input('name','Item name',p?.name||'','text','maxlength="160"')}${input('price','Event price · PHP',amount(p?.price_cents),'number','required min="0" step="0.01"')}<h3>Stock used by one item</h3><p class="muted">Enter 0 for stock this item does not use.</p>${event.stock.map(s=>`<div class="recipe-row"><span>${esc(s.name)}</span><label><span class="muted">Pieces / units</span><input name="recipe_${s.id}" aria-label="${esc(s.name)} units" type="number" min="0" max="10000" step="1" value="${p?.recipe.find(r=>r.stock_id===s.id)?.quantity||0}"></label></div>`).join('')}<label class="check"><input name="active" type="checkbox" ${p?.active!==false?'checked':''}>Available for sale</label><button class="primary" type="submit">Save item</button></form>`,async f=>{await api('pos_save_event_item',{event_id:eventId,id:p?.id||uid(),revision:p?.revision||0,name:f.get('name'),price_cents:cents(f.get('price')),active:f.has('active'),recipe:event.stock.map(s=>({stock_id:s.id,quantity:Number(f.get('recipe_'+s.id))})).filter(r=>r.quantity>0)});await load();dialog.close();render();});}
function customItem(index){const i=Number.isInteger(index)?draft.items[index]:null;modal(i?'Edit custom item':'Add custom item',`<form>${input('name','Custom item name',i?.name||'','text','required maxlength="160"')}<div class="fields">${input('price','Unit price · PHP',amount(i?.unit_price_cents),'number','required min="0" step="0.01"')}${input('quantity','Quantity',i?.quantity||1,'number','required min="1" max="10000" step="1"')}</div><p class="muted">Custom items have no inventory deduction. Choose a website product from the catalog when it should use website stock.</p><button type="submit" class="primary">Save custom item</button></form>`,async f=>{const item={product_id:i?.product_id||uid(),source:'custom',name:f.get('name').trim(),unit_price_cents:cents(f.get('price')),quantity:Number(f.get('quantity')),selections:{}};if(i)draft.items[index]=item;else draft.items.push(item);dialog.close();render();});}
function productForm(p){modal(p?'Edit POS-only product':'Add POS-only product',`<form>${input('name','Product name',p?.name||'','text','maxlength="160"')}${input('price','Price · PHP',amount(p?.price_cents),'number','required min="0" step="0.01"')}${select('stock_mode','Inventory',[['daily','Separate quantity per date'],['running','Running stock across dates'],['unlimited','Unlimited']],p?.stock_mode||'running')}<label class="check"><input name="active" type="checkbox" ${p?.active!==false?'checked':''}>Available for direct orders</label><button class="primary" type="submit">Save product</button></form>`,async f=>{await api('pos_save_product',{id:p?.id||uid(),revision:p?.revision||0,name:f.get('name'),description:p?.description||'',price_cents:cents(f.get('price')),stock_mode:f.get('stock_mode'),photo:p?.photo||'',active:f.has('active')});await load();dialog.close();render();});}
function stockProduct(p){modal('Adjust POS product stock',`<form><p>${esc(p.name)} · ${p.stock_mode==='running'?'All dates':esc(draft.fulfillment_date)}</p>${input('available','Available units now',p.remaining,'number','required min="0" max="1000000" step="1"')}${input('reason','Reason','','text','required maxlength="1000"')}<button class="primary" type="submit">Save stock</button></form>`,async f=>{await api('pos_set_stock',{id:p.id,date:draft.fulfillment_date,available:Number(f.get('available')),expected_available:p.remaining,reason:f.get('reason')});await load();dialog.close();render();});}
async function loadReport(){report=eventId?await api('pos_event_report',{event_id:eventId,date:reportDate}):null;}
function renderReport(){if(!event)return '<p class="notice">Choose an event first.</p>';if(!report)return '<p>Loading report…</p>';const total=report.sales.reduce((s,x)=>s+Number(x.total_cents),0),count=report.sales.reduce((s,x)=>s+Number(x.orders),0),c=report.cash;
 return `<div class="section-head"><label>Report day<input id="report-date" type="date" value="${reportDate}"></label>${button('refresh-report','Refresh report')}</div><div class="metrics"><div class="metric">Sales including delivery<strong>${money(total)}</strong></div><div class="metric">Paid orders<strong>${count}</strong></div><div class="metric">Expected cash in drawer<strong>${c?money(c.expected_cents):'Not opened'}</strong></div></div><section class="panel"><h2>Sales by payment method</h2><p class="muted">Cancelled and refunded orders are excluded. Sales are already included in Accounting.</p><div class="table-wrap"><table><thead><tr><th>Method</th><th>Orders</th><th class="num">Sales</th><th class="num">Delivery included</th></tr></thead><tbody>${report.sales.map(s=>`<tr><td>${esc(s.method)}</td><td>${s.orders}</td><td class="num">${money(s.total_cents)}</td><td class="num">${money(s.delivery_cents)}</td></tr>`).join('')||'<tr><td colspan="4">No sales for this day.</td></tr>'}</tbody></table></div></section><section class="panel"><div class="section-head"><h2>Cash reconciliation</h2><div class="row">${c&&!c.closed_at?button('cash-movement','Record cash in / out')+button('close-cash','Count & close'):c?.closed_at&&role==='owner'?button('reopen-cash','Reopen session'):!c&&reportDate===today()?button('open-cash','Open cash session'):''}</div></div><p class="muted">Expected cash = opening float + cash payments received + cash in − cash out. Cancellations and refund labels do not mean money has left the drawer: record an actual cash refund as cash out. Cash movements do not create extra accounting entries.</p>${c?`<div class="totals"><div><span>Opening float</span><strong>${money(c.opening_cents)}</strong></div><div><span>Expected cash</span><strong>${money(c.expected_cents)}</strong></div>${c.closed_at?`<div><span>Counted cash</span><strong>${money(c.counted_cents)}</strong></div><div class="grand"><span>Over / short at close</span><strong>${money(c.counted_cents-c.expected_at_close)}</strong></div>`:''}</div>`:'<p>No cash session for this date.</p>'}${report.movements.length?`<div class="table-wrap"><table><thead><tr><th>Cash movement</th><th class="num">Amount</th></tr></thead><tbody>${report.movements.map(m=>`<tr><td>${esc(m.reason)}</td><td class="num">${money(m.amount_cents)}</td></tr>`).join('')}</tbody></table></div>`:''}</section><section class="panel"><h2>Remaining event stock</h2><p class="muted">Current stock across the whole event.</p><div class="table-wrap"><table><thead><tr><th>Stock item</th><th class="num">Remaining</th></tr></thead><tbody>${report.stock.map(s=>`<tr><td>${esc(s.name)}</td><td class="num">${s.remaining}</td></tr>`).join('')}</tbody></table></div></section>`;
}
function cashForm(action){const c=view==='report'?report?.cash:event?.cash_session,date=view==='report'?reportDate:today(),movementId=uid();const fields=action==='pos_open_cash'?input('opening','Opening cash float · PHP','0.00','number','required min="0" step="0.01"'):action==='pos_close_cash'?`<p>Expected: <strong>${money(c.expected_cents)}</strong></p>${input('counted','Cash counted · PHP','','number','required min="0" step="0.01"')}`:action==='pos_reopen_cash'?input('reason','Reason for reopening','','text','required maxlength="1000"'):`${select('direction','Cash direction',[['in','Cash in'],['out','Cash out']],'out')}${input('amount','Amount · PHP','','number','required min="0.01" step="0.01"')}${input('reason','Reason (e.g. cash refund, float added)','','text','required maxlength="1000"')}`;
 modal(({pos_open_cash:'Open cash session',pos_close_cash:'Count & close',pos_reopen_cash:'Reopen cash session',pos_cash_movement:'Record cash movement'})[action],`<form>${fields}<button type="submit" class="primary">Save</button></form>`,async f=>{await api(action,{event_id:eventId,date,revision:c?.revision,id:movementId,opening_cents:f.has('opening')?cents(f.get('opening')):undefined,counted_cents:f.has('counted')?cents(f.get('counted')):undefined,expected_cents:c?.expected_cents,amount_cents:f.has('amount')?cents(f.get('amount'))*(f.get('direction')==='out'?-1:1):undefined,reason:f.get('reason')});await load();await loadReport();dialog.close();render();});
}
async function copyPaymentLink(id){const o=await api('pos_payment_link',{order_id:id}),url=new URL('order.html',location.href);url.hash=new URLSearchParams({order:o.id,token:o.token}).toString();try{await navigator.clipboard.writeText(url.href);status('Private order / payment link copied.');}catch{modal('Private payment link',`<p>Anyone with this link can view the order. Send it only to the customer.</p><label>Copy this link<input readonly value="${esc(url.href)}"></label>`);dialog.querySelector('input').select();}}
// Keep the same request on an uncertain network response; known validation failures can be corrected.
function deliveryDialog(title,fields,action,o,values){let request=null;
 modal(title,'<form>'+fields+'<button class="primary subheading" type="submit">Save</button></form>',async f=>{
  request??={order_id:o.id,revision:o.revision,idempotency_key:uid(),...values(f)};
  try{await api(action,request);}catch(e){if(e.code==='P0001'||/^22|^23/.test(e.code||''))request=null;else dialog.querySelectorAll('input,select').forEach(el=>el.disabled=true);throw e;}
  await load();dialog.close();render();status('Delivery details saved.');
 });
}
function deliveryFeeForm(o){const c=o.delivery_charge||{state:'included',recipient:'elio',fee_cents:o.delivery_cents},collected=c.state==='paid'||c.state==='included'&&o.payment_status==='paid'&&c.fee_cents>0;
 if(collected){modal('Delivery payment recorded','<p>'+esc(deliveryFeeSummary(o,money))+'</p><p>Correct the recorded delivery payment before changing who receives it. This does not issue a refund automatically.</p>'+(c.state==='paid'&&role==='owner'?button('void-delivery-payment','Correct delivery payment','data-id="'+o.id+'"'):'<p>This fee was included in the original order payment. Use the kitchen’s payment/refund correction process first.</p>'));return;}
 if(o.payment_status==='under_review'){modal('Payment under review','<p>Finish reviewing the initial payment before changing the delivery fee.</p>');return;}
 const fields='<p><strong>'+esc(o.reference)+'</strong></p>'+select('recipient','Customer pays delivery to',[['elio','Pay Elio'],['courier','Pay courier directly']],c.recipient)+input('fee','Exact delivery fee · PHP',c.fee_cents===null?'':amount(c.fee_cents),'number','min="0" step="0.01"')+'<small>Leave the amount blank while the fee is still to be confirmed.</small>'+input('reason','Reason / booking reference','','text','required maxlength="1000"')+(c.state==='quoted'?'<p>The delivery fee has not been received by Elio. Changing the recipient updates the amount due.</p>'+button('delivery-payment','Record delivery payment','data-id="'+o.id+'"'):'');
 deliveryDialog('Edit delivery fee',fields,'pos_set_delivery_fee',o,f=>({recipient:f.get('recipient'),fee_cents:String(f.get('fee')).trim()===''?null:cents(f.get('fee')),reason:f.get('reason')}));
}
function deliveryPaymentForm(o){const methods=[['cash','Cash'],...(catalog.payment_options||[]).map(x=>[x.label,x.label])];
 deliveryDialog('Record delivery payment','<p>Confirm Elio received <strong>'+money(o.delivery_charge.fee_cents)+'</strong> for delivery. The product payment stays unchanged.</p>'+select('method','Payment method',methods,'cash')+input('reference','Payment reference · optional','','text','maxlength="160"')+'<label class="check"><input type="checkbox" required>Full delivery payment received by Elio</label>','pos_record_delivery_payment',o,f=>({method:f.get('method'),reference:f.get('reference')}));
}
function voidDeliveryPayment(o){deliveryDialog('Correct delivery payment','<p>This reverses the separate delivery receipt in accounting and keeps its history. It does not transfer money.</p><label class="check"><input name="refund_confirmed" type="checkbox" required>The delivery payment was returned to the customer, or was recorded in error</label>'+input('reason','Correction reason','','text','required maxlength="1000"'),'pos_void_delivery_payment',o,f=>({refund_confirmed:f.has('refund_confirmed'),reason:f.get('reason')}));}
function addItem(id){readDraft();const p=product(id);if(!p)return;if(p.kind==='custom_box'){modal('Choose 3 flavor pieces',`<form>${catalog.flavors.map(f=>`<div class="recipe-row"><span>${esc(f.name)}${f.price_cents?`<small>+${money(f.price_cents)} per piece</small>`:''}</span><input type="number" name="${f.id}" aria-label="${esc(f.name)} pieces" min="0" max="3" step="1" value="0"></div>`).join('')}<button class="primary subheading" type="submit">Add box</button></form>`,async f=>{const flavors=Object.fromEntries([...f].filter(([,v])=>Number(v)>0).map(([k,v])=>[k,Number(v)]));if(Object.values(flavors).reduce((a,b)=>a+b,0)!==3)throw Error('Choose exactly 3 pieces.');pushItem(p,{flavors});dialog.close();render();});}else{pushItem(p,{});render();}}
function pushItem(p,selections){const existing=draft.items.find(i=>i.product_id===p.id&&JSON.stringify(i.selections)===JSON.stringify(selections));if(existing)existing.quantity++;else draft.items.push({product_id:p.id,source:p.source||'event',quantity:1,selections,name:p.name});}
async function editOrder(id){const o=await api('get_order',{order_id:id});if(['completed','cancelled','expired'].includes(o.fulfillment_status)||o.refund_label){mode=o.order_source;view='orders';await load();render();return;}if(!['direct','in_person'].includes(o.order_source))throw Error('Use the kitchen editor for this order.');mode=o.order_source;eventId=o.event_id||'';editing=o;draft={...newDraft(),...structuredClone(o),payment:o.pos_payment||{method:'cash',cash_received_cents:0,reference:''},reason:'',items:structuredClone(o.items)};await load();view='sale';render();}
function payOrder(o){let p={method:'cash',cash_received_cents:o.total_cents,reference:''},request=null;const draw=()=>{modal('Record full payment',`<form><p><strong>${esc(o.reference)}</strong> · ${money(o.total_cents)} due</p>${paymentFields(p)}<button class="primary" type="submit">Record payment received</button></form>`,async f=>{request??={order_id:o.id,revision:o.revision,idempotency_key:uid(),payment:{method:f.get('payment_method'),cash_received_cents:cents(f.get('cash_received')||'0'),reference:String(f.get('payment_reference')||'')}};let saved;try{saved=await api('pos_pay_order',request);}catch(error){if(error.code==='P0001'||/^22|^23/.test(error.code||''))request=null;else{dialog.querySelectorAll('input,select').forEach(el=>el.disabled=true);}throw error;}await load();dialog.close();render();showSaved(saved);});dialog.querySelector('[name=payment_method]').onchange=e=>{p.method=e.target.value;dialog.close();draw();};};draw();}
async function action(name,id){
 if(name.startsWith('mode-')){readDraft();if(draft.items.length&&!confirm('Clear this unsaved cart and change POS section?'))return;mode=name==='mode-person'?'in_person':'direct';draft=newDraft();editing=null;view='sale';await load();render();return;}
 if(name.startsWith('view-')){readDraft();view=name.slice(5);if(view==='report')await loadReport();render();return;}
 switch(name){
 case 'delivery-fee':deliveryFeeForm(await api('get_order',{order_id:id}));break;case 'delivery-payment':deliveryPaymentForm(await api('get_order',{order_id:id}));break;case 'void-delivery-payment':voidDeliveryPayment(await api('get_order',{order_id:id}));break;
 case 'custom-item':readDraft();customItem();break;case 'edit-custom-item':readDraft();customItem(Number(id));break;
 case 'new-event':eventForm();break;case 'edit-event':eventForm(event);break;case 'new-event-stock':eventStockForm();break;case 'edit-event-stock':eventStockForm(event.stock.find(x=>x.id===id));break;
 case 'new-event-item':eventItemForm();break;case 'edit-event-item':eventItemForm(event.items.find(x=>x.id===id));break;
 case 'new-product':productForm();break;case 'edit-product':productForm(catalog.pos_products.find(x=>x.id===id));break;case 'stock-product':stockProduct(catalog.pos_products.find(x=>x.id===id));break;
 case 'delete-product':{const p=catalog.pos_products.find(x=>x.id===id);if(confirm(`Delete ${p.name} from the POS catalog? Existing orders and records will stay intact.`)){await api('pos_delete_product',{id,revision:p.revision});await load();render();}break;}
 case 'open-cash':cashForm('pos_open_cash');break;case 'close-cash':cashForm('pos_close_cash');break;case 'reopen-cash':cashForm('pos_reopen_cash');break;case 'cash-movement':cashForm('pos_cash_movement');break;
 case 'refresh-report':await loadReport();render();break;case 'payment-link':await copyPaymentLink(id);break;case 'open-order':location.href=`manage.html?order=${encodeURIComponent(id)}`;break;
 case 'copy-buyer':readDraft();draft.recipient={name:draft.buyer.name,phone:draft.buyer.phone};render();break;case 'back-review':pending=null;render();break;case 'save-sale':await saveSale();break;
 case 'next-sale':dialog.close();view='sale';draft=newDraft();render();break;case 'pay-order':payOrder(orders.find(o=>o.id===id));break;case 'edit-order':await editOrder(id);break;
 case 'cancel-edit':editing=null;draft=newDraft();view='orders';render();break;
 }
}
async function run(fn){if(busy)return;try{busy=true;$('#refresh').disabled=true;await fn();}catch(e){flashError(e);}finally{busy=false;$('#refresh').disabled=false;}}
function bind(){
 root.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>run(()=>addItem(b.dataset.add)));
 root.querySelectorAll('[data-qty]').forEach(i=>i.onchange=()=>run(()=>{readDraft();const n=Number(i.value);if(!Number.isInteger(n)||n<1||n>10000)throw Error('Enter a whole quantity between 1 and 10,000.');draft.items[Number(i.dataset.qty)].quantity=n;render();}));
 root.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>run(()=>{readDraft();draft.items.splice(Number(b.dataset.remove),1);render();}));
 const f=$('#sale-form');if(f){f.onsubmit=e=>{e.preventDefault();run(review);};for(const name of ['method','paid','payment_method','pos_handed_over','delivery_fee_recipient','delivery_fee_pending'])f.elements[name]?.addEventListener('change',()=>run(()=>{readDraft();render();}));f.elements.fulfillment_date.onchange=()=>run(async()=>{readDraft();catalog=await api('pos_catalog',{date:draft.fulfillment_date});render();});f.elements.cash_received?.addEventListener('input',e=>{const value=Number(e.target.value);if($('#cash-change'))$('#cash-change').textContent=money(Math.max(0,Math.round(value*100)-estimated()));});}
 $('#search')?.addEventListener('input',e=>{search=e.target.value;const cursor=e.target.selectionStart;readDraft();render();$('#search').focus();$('#search').setSelectionRange(cursor,cursor);});
 $('#event-select')?.addEventListener('change',e=>run(async()=>{if(draft.items.length&&!confirm('Clear the current cart and switch event?')){e.target.value=eventId;return;}eventId=e.target.value;draft=newDraft();await load();if(view==='report')await loadReport();render();}));
 $('#report-date')?.addEventListener('change',e=>run(async()=>{reportDate=e.target.value;await loadReport();render();}));
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b){e.preventDefault();run(()=>action(b.dataset.action,b.dataset.id));}});
$('#refresh').onclick=()=>run(async()=>{if(pending){status('Finish or retry the pending request first.');return;}readDraft();await load();if(view==='report')await loadReport();render();status('Stock and orders refreshed.');});
window.addEventListener('beforeunload',e=>{if(pending||draft.items.length){e.preventDefault();e.returnValue='';}});
window.addEventListener('offline',()=>{status('Connection lost. Sales require internet.');});window.addEventListener('online',()=>status('Connection restored. Refresh to see current stock.'));
await ready;
try{const access=await api('account_access');if(!['owner','staff'].includes(access.role))throw Error('Sign in with an authorized Elio team account.');role=access.role;await load();const edit=new URLSearchParams(location.search).get('edit');if(edit)await editOrder(edit);else render();auth?.onAuthStateChange(event=>{if(event==='SIGNED_OUT'){draft=newDraft();pending=null;location.replace('admin-account.html?next=pos.html');}});if('serviceWorker' in navigator)navigator.serviceWorker.register('pos-sw.js',{scope:'./'}).catch(()=>{});}catch(error){root.innerHTML=`<section class="panel"><h1>Elio POS</h1><p>${esc(error.message)}</p><a class="button" href="admin-account.html?next=pos.html">Team sign in</a></section>`;}
